"proposal": {
  "capability": "deployment.set-resources",
  "target": {"group": "apps", "kind": "Deployment", "namespace": "shop", "name": "search", "uid": "uid-deployment-search"},
  "params": {
    "containers": {
      "app": {
        "limits": {
          "cpu": "300m"
        }
      }
    }
  },
  "expected_effect": "The container's CPU limit will be increased from 200m to 300m, reducing throttling and allowing the app to use more CPU without being constrained.",
  "rationale": "The container is consistently throttled at its current CPU limit of 200m, with usage at 91.5% of the limit. Increasing the limit to 300m (1.5x current) should clear the throttling without affecting memory or other resources. No prior revision exists to compare, so this is the most likely fix for the observed throttling.",
